local _, ns = ...
if ns.LOCALE ~= "itIT" then return end
local L = ns.L

-- Options/Welcome.lua: What's New, by version (WN<id>_<n>), newest first; beside Locales/itIT.lua.
L["WN29_1_TITLE"] = "Una finestra Eredità classica"
L["WN29_1_TEXT"] = "Il pulsante e il tasto Eredità aprono una finestra Eredità classica: il percorso delle ricompense e le sfide sulle vecchie barre delle abilità, con ricerca e filtro, e gli alberi dell'Eredità nella vecchia finestra dei talenti. Attiva di base; disattivala nelle opzioni (/fcui), in Personaggio e incantesimi."
L["WN29_2_TITLE"] = "I tuoi layout restano tuoi"
L["WN29_2_TEXT"] = "Con l'addon disattivato, le barre delle azioni nei tuoi layout della modalità Modifica non stanno più ai posti della barra classica. I posti salvati lì in precedenza vengono restituiti la prossima volta che premi Ricarica IU nelle opzioni (/fcui) o scrivi /fcui off."
L["WN29_3_TITLE"] = "Correzioni"
L["WN29_3_TEXT"] = "/fcui off disattiva di nuovo l'addon. Cliccare un membro della gilda in combattimento apre i suoi dettagli. La finestra delle impostazioni del gioco non si riempie più di errori dopo un combattimento, i livelli delle missioni restano nascosti con l'opzione disattivata e la freccia per scorrere in fondo alla chat non lampeggia più."
L["WN29_4_TITLE"] = "Spazi delle armi"
L["WN29_4_TEXT"] = "Gli spazi delle armi nella finestra del personaggio sono centrati su due incavi, senza l'incavo vuoto dello spazio a distanza."
L["WN28_1_TITLE"] = "Alleati recenti e Ignorati"
L["WN28_1_TEXT"] = "La scheda Amici della finestra sociale ha le schede Alleati recenti e Ignorati accanto ad Amici. Alleati recenti elenca i giocatori con cui sei stato in gruppo di recente e ha una riga di ricerca; Ignorati elenca i giocatori che ignori."
L["WN28_2_TITLE"] = "Di nuovo la finestra sociale classica"
L["WN28_2_TEXT"] = "Dopo l'ultimo aggiornamento del gioco, O e il pulsante della gilda aprivano la nuova finestra sociale del gioco. Ora aprono di nuovo quella classica, le sue schede sono allineate e la scheda Incursione è tornata."
L["WN28_3_TITLE"] = "Correzioni dopo l'aggiornamento del gioco"
L["WN28_3_TEXT"] = "I punti combo mostrano di nuovo tutti e cinque i globi classici. La striscia scura sul modello del personaggio e il riquadro scuro sulle pagine degli annunci della ricerca di gruppo sono spariti, il pulsante di ordinamento funziona in modalità borsa unica, e la ricerca di gruppo non salta più quando la si apre in combattimento."
L["WN28_4_TITLE"] = "Finestra del bottino e borse"
L["WN28_4_TEXT"] = "Con Finestra del bottino disattivata, la finestra del bottino del gioco non mostra più due quadrati bianchi negli angoli. Il pulsante di ordinamento delle borse sta accanto alla casella di ricerca."
L["WN27_1_TITLE"] = "Meno lavoro in background"
L["WN27_1_TEXT"] = "Le targhette vengono disposte di nuovo solo quando cambia un'impostazione delle targhette, non a ogni impostazione modificata dal gioco o da un altro addon. Le coordinate della minimappa vengono misurate solo quando cambiano. Nulla cambia nell'aspetto."
L["WN26_1_TITLE"] ="Colori di classe per riquadro"
L["WN26_1_TEXT"] = "Salute col colore della classe e Riquadro del nome col colore della classe sono disattivate di base; attivale nelle opzioni (/fcui), in Riquadri delle unità. Ognuna ha ora sotto un menu dei riquadri: Giocatore, Bersaglio e Focus, così il bersaglio può portare il colore della sua classe mentre il tuo riquadro resta com'era."
L["WN26_2_TITLE"] = "Colore del riquadro del nome"
L["WN26_2_TEXT"] = "Un nuovo menu Colore del riquadro del nome, in Riquadri delle unità, sceglie in quali riquadri il riquadro del nome prende il colore del gioco per l'unità (blu per un giocatore amico). Bersaglio e Focus sono spuntati, come in Classic Era; togli la spunta per un riquadro senza colore. Giocatore è disattivato di base; attivalo nelle opzioni (/fcui) per colorare il tuo."
L["WN26_3_TITLE"] = "Correzioni"
L["WN26_3_TEXT"] = "Con la barra della salute spessa sopra il nome, il riquadro del nome del giocatore non si vede più dietro la barra. Togliendo la spunta al riquadro del nome col colore della classe, il colore sparisce subito dal bersaglio e dal focus."
L["WN25_1_TITLE"] = "Grifoni"
L["WN25_1_TEXT"] = "I grifoni ora vengono salvati con il layout della modalità modifica, come gli elementi del gioco: ogni layout mantiene i propri posti per loro, e Salva su un layout predefinito del gioco chiede un nuovo layout, che li riceve. Uno spostamento non salvato viene scartato alla chiusura della modalità modifica. Il layout classico nelle opzioni li riporta alle estremità della barra."
L["WN24_1_TITLE"] = "Borse"
L["WN24_1_TEXT"] = "Le borse aperte non saltano più di lato quando equipaggi un oggetto con il clic destro, in combattimento o fuori."
L["WN23_1_TITLE"] = "Timer dei colpi"
L["WN23_1_TEXT"] = "Cambiare arma in combattimento non provoca più un errore Lua a ogni fotogramma in cui la barra dei colpi è visibile, e il lampo a ogni colpo continua a funzionare dopo il cambio."
L["WN22_1_TITLE"] = "Professioni"
L["WN22_1_TEXT"] = "Una professione si apre nella finestra classica delle abilità commerciali, e il libro delle professioni è quello vecchio e piccolo, nella cornice del grimorio. Il pulsante della dimensione accanto a quello di chiusura porta l'uno o l'altro alla finestra completa del gioco."
L["WN22_2_TITLE"] = "Grimorio e talenti"
L["WN22_2_TEXT"] = "Un pulsante Grimorio nel micromenu, accanto a Personaggio, apre il grimorio classico. La finestra dei talenti del gioco porta la cornice classica, e il pulsante Talenti la apre sempre sui tuoi talenti."
L["WN22_3_TITLE"] = "Micromenu e minimappa"
L["WN22_3_TEXT"] = "Imprese, Guida alle avventure e Alloggi escono dal micromenu, perché la 1.x non li aveva, e ognuno ha un'icona sulla minimappa. Per riavere un pulsante, togli la spunta in Nascondi micropulsanti nelle opzioni (/fcui)."
L["WN22_4_TITLE"] = "Unione rapida"
L["WN22_4_TEXT"] = "Unione rapida ha lasciato la fila di schede della finestra sociale. Apri Amici, poi Alleati recenti: la scheda Unione rapida sotto l'elenco porta lì, e la scheda Alleati recenti torna indietro."
L["WN22_5_TITLE"] = "Prestazioni"
L["WN22_5_TEXT"] = "I temi di colore usano molta meno CPU: la grafica colorata segue quella del gioco solo quando qualcosa cambia, non a ogni fotogramma. I menu del clic destro sui ritratti, le borse e le finestre si aprono senza scatti."
L["WN22_6_TITLE"] = "Macro"
L["WN22_6_TEXT"] = "Un incantesimo portato con Maiusc-clic dal grimorio classico in una macro entra con nome e grado, come dal grimorio del gioco; prima entrava come un collegamento di chat, che una macro non può lanciare. La finestra delle macro ha le schede di Classic Era."
L["WN22_7_TITLE"] = "Macro"
L["WN22_7_TEXT"] = "Un incantesimo portato con Maiusc-clic dal grimorio classico in una macro entra con nome e grado, come dal grimorio del gioco; prima entrava come un collegamento di chat, che una macro non può lanciare. Anche i talenti entrano con il loro nome. La finestra delle macro ha le schede di Classic Era."
L["WN22_8_TITLE"] = "Menu a tendina"
L["WN22_8_TEXT"] = "I menu a tendina del gioco, come il menu di stato (Disponibile, Assente, Occupato) e il menu di tracciamento della minimappa, hanno ora la cornice di ferro di Classic Era, che contiene le loro icone e frecce."
L["WN22_9_TITLE"] = "Reputazione e valute"
L["WN22_9_TEXT"] = "Entrambe le schede mantengono le righe classiche: spaziatura uniforme, le vecchie intestazioni, una sola colonna di barre. Un gruppo di fazioni ha il suo pulsante più o meno con le sue fazioni rientrate sotto, e il filtro è un piccolo pulsante a freccia in alto a destra."
L["WN22_10_TITLE"] = "Altre correzioni"
L["WN22_10_TEXT"] = "Le schede sotto una finestra restano sul suo bordo inferiore; con alcune dimensioni dell'interfaccia salivano. Maiusc-clic su una professione lascia aperto il grimorio, i numeri del mana di un druido nelle forme seguono l'impostazione Testo di stato del gioco, e la scheda Aiuto mostra solo le domande per la versione del gioco a cui giochi."
L["WN22_11_TITLE"] = "Finestre su Retail"
L["WN22_11_TEXT"] = "La borsa dei reagenti resta libera dalla barra della latenza, la finestra del personaggio non ha linee sottili intorno al modello, la finestra sociale ha una sola scheda Chi, e i bordi delle finestre stanno come su Forever."
L["WN21_1_TITLE"] = "Elenco di gilda"
L["WN21_1_TEXT"] = "Un clic su un membro apre le sue note e opzioni per ogni membro; nelle gilde più grandi per molti non si apriva nulla. L'elenco usa anche molta meno CPU mentre è aperto."
L["WN21_2_TITLE"] = "Condivisione delle missioni"
L["WN21_2_TEXT"] = "Condividi missione nel registro delle missioni classico funziona per qualsiasi missione con un solo clic, anche subito dopo l'accesso. Funzionava solo per le missioni della zona mostrata per ultima dalla mappa del mondo."
L["WN21_3_TITLE"] = "Finestre"
L["WN21_3_TEXT"] = "Una lettera aperta ha la cornice classica della finestra, come la posta in arrivo, e il pannello laterale della finestra del personaggio non mostra più una sottile linea trasparente con alcune dimensioni dell'interfaccia."
L["WN20_1_TITLE"] ="Dettagli del grado PvP"
L["WN20_1_TEXT"] = "La scheda PvP della finestra del personaggio può mostrare i dettagli del tuo grado e le ricompense del grado successivo. Fai clic sulla freccia in basso a destra della scheda per aprire il pannello laterale."
L["WN20_2_TITLE"] = "Borsa dei pulsanti degli addon"
L["WN20_2_TEXT"] = "La sua posizione predefinita è ora a sinistra dell'orologio, lontano dall'occhio della ricerca gruppi, e lascia sulla minimappa le nostre icone, come Eredità. Il pulsante Disposizione classica rimette a posto anche i pulsanti della minimappa che hai spostato."
L["WN20_3_TITLE"] = "Altri addon"
L["WN20_3_TEXT"] = "Le parti di ClassicUI Forever che disattivi ora lasciano stare i riquadri del gioco, così gli addon che li modificano mantengono il loro aspetto."
L["WN19_1_TITLE"] = "Icone della minimappa"
L["WN19_1_TEXT"] = "Qualsiasi pulsante del micromenu può ora stare sulla minimappa come icona: selezionalo in Pulsanti del micromenu sulla minimappa, nelle opzioni (/fcui). Eredità e la ricerca gruppi sono attivi di base, così Eredità ha di nuovo un accesso. Tieni premuto Maiusc e trascina per spostare i nostri pulsanti della minimappa intorno all'anello."
L["WN19_2_TITLE"] = "Tracciamento missioni"
L["WN19_2_TEXT"] = "Il tracciamento degli obiettivi può essere il semplice tracciamento missioni di Classic Era. Disattivato di base; per attivarlo, imposta Tracciamento degli obiettivi su quello di Classic Era nelle opzioni (/fcui), in Missioni. Clic su un titolo per aprire la missione, Maiusc-clic per non seguirla più, clic destro per altro."
L["WN19_3_TITLE"] = "Finestra delle opzioni"
L["WN19_3_TEXT"] = "La finestra delle opzioni è più grande e i suoi lunghi elenchi sono ora menu a tendina, così c'è meno da scorrere."
L["WN19_4_TITLE"] = "Percentuale di minaccia"
L["WN19_4_TEXT"] = "La percentuale di minaccia può comparire solo in gruppo o spedizione: attiva Solo in gruppo o spedizione nelle opzioni (/fcui), in Riquadri delle unità. Disattivato di base."
L["WN19_5_TITLE"] = "Dettagli di Classic Era"
L["WN19_5_TEXT"] = "Il suggerimento del pulsante del menu di gioco ha le descrizioni di Classic Era, i menu a tendina usano la cornice di ferro di Classic Era e i pulsanti del micromenu non diventano più grigi con il menu di gioco aperto."
L["WN19_6_TITLE"] = "Correzioni"
L["WN19_6_TEXT"] = "Ripristina opzioni mantiene le barre di dimensione classica, i temi personalizzati colorano per intero le schede delle opzioni, la grafica della barra classica resta visibile nella disposizione ClassicUI Forever, il pulsante delle opzioni non copre più la lente del tracciamento e, con Minimappa deselezionata, le icone della minimappa nascoste da un altro addon restano nascoste."
L["WN18_1_TITLE"] = "Professioni"
L["WN18_1_TEXT"] = "La finestra della professione ora può seguire una ricetta (i suoi reagenti compaiono nel tracciamento degli obiettivi), filtrare per slot dell'equipaggiamento e collegare la tua professione in chat con l'anello di catena accanto al titolo. Il tasto delle professioni apre di nuovo il libro delle professioni."
L["WN18_2_TITLE"] = "Draghi élite"
L["WN18_2_TEXT"] = "I nemici élite possono mostrare un drago dorato intorno al livello sulla targhetta, i rari uno argentato: attiva Draghi élite nelle opzioni (/fcui), in Targhette. Con un tema personalizzato, Ignora il tema per i riquadri élite e Ignora il tema per i draghi delle targhette, in Tema personalizzato, mantengono i draghi dorati e argentati. Tutto disattivato di base."
L["WN18_3_TITLE"] = "Bagliore di combattimento"
L["WN18_3_TEXT"] = "Per fermare la pulsazione rossa del riquadro del giocatore mentre attacchi, attiva Nascondi bagliore di combattimento nelle opzioni (/fcui), in Riquadri delle unità. Disattivato di base."
L["WN18_4_TITLE"] = "Barre di lancio"
L["WN18_4_TEXT"] = "I lanci interrotti di bersaglio, focus e targhette ora diventano rossi e dicono solo Interrotto, come in Classic Era. Per vedere chi ha interrotto, attiva Nomina chi interrompe nelle opzioni (/fcui), in Barre di lancio. Le canalizzazioni appaiono in verde."
L["WN18_5_TITLE"] = "Difficoltà dell'istanza"
L["WN18_5_TEXT"] = "La bandiera di difficoltà che il gioco mostra sulla minimappa in spedizioni e incursioni ora è nascosta. Per riaverla, scegli visibile o al passaggio in Minimappa, nelle opzioni (/fcui)."
L["WN18_6_TITLE"] = "Disposizione classica"
L["WN18_6_TEXT"] = "La figura della durabilità non si nasconde più dietro le barre laterali, e i benefici stanno nei punti di Classic Era accanto alla minimappa. La disposizione offre anche la dimensione dell'interfaccia di Classic Era quando la tua è diversa."
L["WN18_7_TITLE"] = "Aspetto"
L["WN18_7_TEXT"] = "I menu hanno lo sfondo nero di Classic Era, e le targhette hanno la dimensione di Classic Era. La parte vuota delle barre di esperienza e reputazione è ombreggiata come in Classic Era; per togliere l'ombra, deseleziona Barre di esperienza e reputazione ombreggiate in Barra classica."
L["WN18_8_TITLE"] = "Correzioni"
L["WN18_8_TEXT"] = "Addestra funziona per le ricette in fondo alla lista di un istruttore. I pulsanti della chat restano su ogni scheda, e Maiusc-clic collega un talento in chat. La mappa del mondo aperta in combattimento non cattura più i clic, e i pulsanti rossi della modalità modifica restano interi quando cambi tema."
L["WN17_1_TITLE"] = "Errori delle targhette"
L["WN17_1_TEXT"] = "Con un tema attivo, le targhette classiche non causano più messaggi di errore."
L["WN17_2_TITLE"] = "Benefici del bersaglio"
L["WN17_2_TEXT"] = "I benefici sotto i riquadri del bersaglio e del focus ora compaiono subito al loro posto quando cambi bersaglio, senza il breve salto."
L["WN17_3_TITLE"] = "Mappa del mondo in combattimento"
L["WN17_3_TEXT"] = "La mappa del mondo classica aperta in combattimento ora ha lo stesso aspetto che fuori dal combattimento."
L["WN16_1_TITLE"] = "Icone delle azioni"
L["WN16_1_TEXT"] = "Con un tema attivo, le icone dei pulsanti azione non si scuriscono più a caso."
L["WN16_2_TITLE"] = "Bagliore di combattimento"
L["WN16_2_TEXT"] = "Con Barre della salute spesse sopra il nome, il bagliore rosso di combattimento e quello dorato di riposo ora circondano l'intero riquadro del giocatore invece della barra della salute. Le Barre della salute spesse sono disattivate di base; attivale nelle opzioni (/fcui), sotto Riquadri delle unità."
L["WN16_3_TITLE"] = "Targhette"
L["WN16_3_TEXT"] = "Con le targhette classiche disattivate, le targhette del gioco non causano più messaggi di errore."
L["WN15_1_TITLE"] = "Minaccia"
L["WN15_1_TEXT"] = "La percentuale di minaccia di Classic Era ora compare sopra i riquadri del bersaglio e del focus in combattimento. Il bagliore rosso attorno ai riquadri delle unità ora è nascosto di base; per riaverlo, togli la spunta a Nascondi bagliore di minaccia nelle opzioni (/fcui), sotto Riquadri delle unità."
L["WN15_2_TITLE"] = "Mana del druido"
L["WN15_2_TEXT"] = "In forma di orso e di felino, i druidi ora vedono il loro mana in una piccola barra sotto la barra dell'ira o dell'energia."
L["WN15_3_TITLE"] = "Colore della salute nemica"
L["WN15_3_TEXT"] = "Disattivato di base. Per usarlo, attiva Barre della salute spesse nelle opzioni (/fcui), sotto Riquadri delle unità, poi scegli Per reazione sotto Salute nemica: i nemici neutrali hanno la barra gialla, quelli ostili rossa."
L["WN15_4_TITLE"] = "Testo in inglese"
L["WN15_4_TEXT"] = "Per un gioco in un'altra lingua: i testi propri di questo addon possono comparire in inglese, parte per parte. Disattivato di base; attivalo nelle opzioni (/fcui), sotto Altro, Testo in inglese."
L["WN15_5_TITLE"] = "Elenco Chi"
L["WN15_5_TEXT"] = "La freccia in cima all'ultima colonna dell'Elenco Chi ora contiene i filtri di classe, razza e zona del gioco. Una ricerca con uno o due risultati resta nella finestra invece di finire in chat."
L["WN15_6_TITLE"] = "Colore piatto"
L["WN15_6_TEXT"] = "Colore piatto dipinge la grafica di finestre e barre in un unico colore pieno invece del metallo. Ora mantiene le linee sottili dentro le finestre, attorno a elenchi, piè di pagina e divisori, a meno che tu non attivi anche Nascondi bordi interni. Entrambi sono disattivati di base: attiva Tema personalizzato, poi Colore piatto, nelle opzioni (/fcui), sotto Aspetto."
L["WN15_7_TITLE"] = "Timer dei colpi"
L["WN15_7_TEXT"] = "I timer dei colpi ora possono funzionare senza il lampo dopo ogni colpo: togli la spunta a Lampo a ogni colpo nelle opzioni (/fcui), sotto Timer dei colpi."
L["WN15_8_TITLE"] = "Targhette"
L["WN15_8_TEXT"] = "I nomi e i piccoli numeri delle targhette ora usano il testo semplice di Classic Era. Nuovo e disattivato di base: Stessa dimensione vicino e lontano mantiene tutte le targhette della stessa dimensione, come in Classic Era; attivalo nelle opzioni (/fcui), sotto Targhette."
L["WN15_9_TITLE"] = "Finestre"
L["WN15_9_TEXT"] = "Le finestre delle missioni, dei dialoghi e del mercante e l'elenco del registro missioni ora hanno il bordo sottile di Classic Era attorno al contenuto, e la finestra del personaggio mostra il volto del tuo personaggio in ogni scheda."
L["WN15_10_TITLE"] = "Correzioni"
L["WN15_10_TEXT"] = "Con un tema attivo, i bordi delle icone, gli anelli dei ritratti, i menu e le frecce di pagina del mercante prendono il suo colore, e i cursori restano visibili. Le schede della finestra del personaggio ora rispondono dove sono disegnate."
L["WN14_1_TITLE"] = "Controller"
L["WN14_1_TEXT"] = "Con l'interfaccia gamepad attiva, il libro degli incantesimi classico, i talenti e il registro delle missioni si aprono nelle finestre del gioco stesso, così un controller può muoversi al loro interno."
L["WN14_2_TITLE"] = "Tema ovunque"
L["WN14_2_TEXT"] = "Con un tema attivo, anche i pezzi del gioco stesso prendono il suo colore dove hai lasciato spenti quelli classici: minimappa, riquadri delle unità, barre, finestre e i pulsanti del menu di gioco."
L["WN14_3_TITLE"] = "Oscurità"
L["WN14_3_TEXT"] = "Scuro ha un cursore dal grigio chiaro al nero, con un pulsante per tornare al valore predefinito."
L["WN14_4_TITLE"] = "Colore piatto"
L["WN14_4_TEXT"] = "Colore piatto (Tema personalizzato) mostra le parti spuntate in un solo colore piatto, nelle stesse forme."
L["WN14_5_TITLE"] = "Micropulsanti"
L["WN14_5_TEXT"] = "Nascondi micropulsanti ora funziona sul micromenu del gioco stesso con la barra classica spenta, e può nascondere il negozio."
L["WN14_6_TITLE"] = "Barre da 6 a 8"
L["WN14_6_TEXT"] = "Nascondi barre da 6 a 8 non c'è più: decidono le impostazioni delle barre azione del gioco."
L["WN14_7_TITLE"] = "Correzioni"
L["WN14_7_TEXT"] = "Coordinate: nascoste e al passaggio funzionano con la minimappa del gioco, i pulsanti della minimappa di altri add-on prendono il tema, e lo zaino di un cacciatore mostra gli spazi liberi invece delle munizioni."
L["WN13_1_TITLE"] = "Bagliore di minaccia"
L["WN13_1_TEXT"] = "Nascondi bagliore di minaccia (Riquadri delle unità) toglie il bagliore rosso di minaccia dai riquadri delle unità. Il numero di minaccia del gioco resta."
L["WN13_2_TITLE"] = "Oggetti delle missioni"
L["WN13_2_TEXT"] = "Oggetti delle missioni semplici (Finestre delle borse) mostra gli oggetti delle missioni in borse e banca senza il bordo della missione."
L["WN13_3_TITLE"] = "Numeri"
L["WN13_3_TEXT"] = "Numeri senza separatori (Riquadri delle unità) toglie i separatori delle migliaia dai numeri grandi, sulle barre e in tutto il gioco."
L["WN13_4_TITLE"] = "Icone delle azioni"
L["WN13_4_TEXT"] = "Con un tema attivo, le icone delle azioni tornano intere, come in Classic Era; solo il loro bordo prende il colore del tema."
L["WN13_5_TITLE"] = "Le tue barre"
L["WN13_5_TEXT"] = "Se la 0.14.0 ha cambiato le tue barre, una riga in chat all'accesso ti permette di riportarle com'erano o di scegliere l'aspetto classico."
L["WN13_6_TITLE"] = "Finestra social"
L["WN13_6_TEXT"] = "Le schede Amici e Incursione stanno nel loro bordo sottile come in Classic Era, e la descrizione della scheda Incursione si vede di nuovo fuori da un'incursione."
L["WN13_7_TITLE"] = "Correzioni"
L["WN13_7_TEXT"] = "Il bottino sotto il mouse si apre con il primo oggetto sotto il cursore, le etichette delle schede diventano bianche al passaggio, e Disposizione classica riporta il micromenu e le caselle delle borse classici."
L["WN12_1_TITLE"] = "Finestre"
L["WN12_1_TEXT"] = "Accanto al pulsante di chiusura di ogni finestra ci sono un blocco e un ripristino: sbloccata, la finestra si trascina dal titolo. Le finestre delle missioni e del dialogo, la finestra social, la ricerca gruppi e il libro delle professioni si posizionano e si ridimensionano in Finestre di ClassicUI Forever."
L["WN12_2_TITLE"] = "Timer dei colpi"
L["WN12_2_TEXT"] = "I timer dei colpi del gioco con l'aspetto della barra di lancio 1.x, un colore per mano e un lampo a ogni colpo. I colori e lo Spessore del bordo si scelgono nelle opzioni."
L["WN12_3_TITLE"] = "Barre della salute spesse"
L["WN12_3_TEXT"] = "Una barra della salute più alta sui riquadri di giocatore, bersaglio e focus, sopra il nome o sopra il mana (Riquadri delle unità). Lì sono nuovi anche Riquadro del nome col colore della classe e Dimensione dei nomi."
L["WN12_4_TITLE"] = "Grifoni"
L["WN12_4_TEXT"] = "I grifoni si trascinano, si ridimensionano o si nascondono nella modalità modifica del gioco. Con l'aggancio attivo si allineano alle barre e tornano al loro posto."
L["WN12_5_TITLE"] = "Misuratore dei danni"
L["WN12_5_TEXT"] = "Il misuratore dei danni nella cornice 1.x, con pulsanti classici e uno sfondo di marmo o di albero dei talenti che si può spostare."
L["WN12_6_TITLE"] = "Lingue"
L["WN12_6_TEXT"] = "ClassicUI Forever ora è in tedesco, francese, spagnolo e italiano."
L["WN12_7_TITLE"] = "Opzioni"
L["WN12_7_TEXT"] = "Nuove schede FAQ e Supporto, un Colore personalizzato per il tema e una ricerca che trova un'impostazione con più nomi."
L["WN12_8_TITLE"] = "Risorse"
L["WN12_8_TEXT"] = "La visualizzazione personale delle risorse in barre 1.x con il vecchio bordo delle targhette, con l'impostazione Distanza delle barre."
L["WN12_9_TITLE"] = "Barra classica"
L["WN12_9_TEXT"] = "Caselle delle borse di dimensione classica, ogni micropulsante si può nascondere, il pulsante Aiuto torna in fondo al micromenu e La fascia regge le barre 2 e 3 tiene quelle barre sulla fascia."
L["WN12_10_TITLE"] = "Minimappa e chat"
L["WN12_10_TEXT"] = "Coordinate e un bordo e un'intestazione nascondibili sulla minimappa, l'occhio della ricerca gruppi sopra di essa quando il suo micropulsante è nascosto, e ogni pulsante della chat si nasconde da solo."
L["WN12_11_TITLE"] = "Correzioni"
L["WN12_11_TEXT"] = "Le barre non saltano più in cima allo schermo dopo un trascinamento in modalità modifica, la barra 1 si sposta con le frecce in modalità modifica, la barra dell'esperienza non appare più doppia dopo un accesso in combattimento e le pagine del bottino non ripetono più oggetti."
L["WN12_12_TITLE"] = "Correzioni minori"
L["WN12_12_TEXT"] = "I numeri del famiglio e del gruppo stanno nelle loro barre, il micromenu non salta più quando lo si trascina, la barra della latenza mantiene la sua cornice e i suggerimenti dei micropulsanti appaiono una volta con il limite di missioni giusto."
L["WN11_1_TITLE"] = "Chat"
L["WN11_1_TEXT"] = "Nascondi pulsanti della chat permette alla chat di stare sul bordo dello schermo, e Barra di scorrimento della chat mantiene quella di WoW Forever (Pulsanti della chat)."
L["WN11_2_TITLE"] = "Livelli delle missioni"
L["WN11_2_TEXT"] = "Livelli delle missioni (Missioni) mostra il livello di ogni missione sulla mappa, nel tracciamento e nel registro delle missioni, in linea con il filtro della mappa."
L["WN11_3_TITLE"] = "Tema scuro"
L["WN11_3_TEXT"] = "I menu del clic destro, i pulsanti della minimappa degli addon, i pulsanti dello zoom, l'orologio e l'icona giorno e notte prendono il tema, e le icone d'azione non mostrano il bordo chiaro."
L["WN11_4_TITLE"] = "Correzioni"
L["WN11_4_TEXT"] = "Niente livello doppio delle missioni nel tracciamento, niente errori dai menu del clic destro nelle spedizioni, e il menu del bersaglio resta sullo schermo."
L["WN10_1_TITLE"] = "Minimappa"
L["WN10_1_TEXT"] = "Ogni parte della minimappa può mostrarsi, mostrarsi solo al passaggio o nascondersi (Minimappa nelle opzioni), e ingrandisci e rimpicciolisci si spostano ognuno intorno all'anello in Finestre di ClassicUI Forever."
L["WN10_2_TITLE"] = "Micromenu"
L["WN10_2_TEXT"] = "Le descrizioni di Classic Era nelle descrizioni dei micropulsanti, e Nascondi micropulsanti toglie singoli pulsanti dal menu (Barra classica)."
L["WN10_3_TITLE"] = "Portachiavi"
L["WN10_3_TEXT"] = "Si apre anche senza chiavi, nella sua finestra, con la grafica di Classic Era."
L["WN10_4_TITLE"] = "Nuove opzioni"
L["WN10_4_TEXT"] = "Nascondi barra delle posizioni (Barra classica), Dimensione del testo del nome (Targhette) e Descrizione dell'unità sulle barre (Riquadri delle unità)."
L["WN10_5_TITLE"] = "Correzioni"
L["WN10_5_TEXT"] = "Le frecce di scorrimento diventano grigie quando non c'è nulla da scorrere, il registro delle missioni evidenzia come in Classic Era, Ultimo accesso della gilda si ordina bene e la finestra delle macro si apre accanto al libro degli incantesimi."
L["WN10_6_TITLE"] = "Correzioni minori"
L["WN10_6_TEXT"] = "Le frecce dei talenti, la scheda della gilda senza gilda, le frecce di pagina sopra la mappa, la borsa dei pulsanti degli addon e richieste di disposizione più brevi."
L["WN9_1_TITLE"] = "Mappa del mondo classica"
L["WN9_1_TEXT"] = "La mappa piccola di Classic Era, con l'elenco missioni della mappa nel suo riquadro accanto e le ricompense dopo il testo della missione. Barra di navigazione della mappa in Mappa nelle opzioni riporta la disposizione di mappa del gioco."
L["WN9_2_TITLE"] = "Nuove opzioni"
L["WN9_2_TEXT"] = "Nascondi pulsante delle missioni della mappa (Mappa), Barre di dimensione classica (Barra classica) e Scossa all'interruzione (Barre di lancio)."
L["WN9_3_TITLE"] = "Stile classico"
L["WN9_3_TEXT"] = "I menu del clic destro, i menu a tendina, la finestra sociale, la ricerca gruppi, l'elenco Chi e l'elenco della gilda seguono Classic Era; la finestra delle impostazioni prende l'aspetto del client attuale di Classic Era, e l'elenco degli ignorati e il camerino lo stile classico."
L["WN9_4_TITLE"] = "Modalità modifica"
L["WN9_4_TEXT"] = "Il libro degli incantesimi si può spostare e ridimensionare in Finestre di ClassicUI Forever."
L["WN9_5_TITLE"] = "Barre e tracciamento"
L["WN9_5_TEXT"] = "Le barre 4 e 5 mantengono il loro posto sul bordo dello schermo, e il tracciamento delle missioni non ci sta più sopra."
L["WN9_6_TITLE"] = "Correzioni"
L["WN9_6_TEXT"] = "I PNG neutrali mostrano il loro livello al posto di un teschio, e cliccare le barre di un riquadro delle unità seleziona di nuovo il bersaglio."
L["WN9_7_TITLE"] = "Finestre e schede"
L["WN9_7_TEXT"] = "Le finestre del mercante, della posta, dello statuto di gilda e della tabarda, e molte altre finestre e schede, si allineano a Classic Era; Esc chiude la finestra dello statuto di gilda."
L["WN8_1_TITLE"] = "Grifoni sopra le barre"
L["WN8_1_TEXT"] = "Spunta Grifoni sopra le barre in Barra classica nelle opzioni per disegnare i grifoni davanti alle barre 2 e 3."
L["WN8_2_TITLE"] = "Finestre che si aprono alla pressione"
L["WN8_2_TEXT"] = "I tasti di libro degli incantesimi, professioni, talenti, gilda e registro delle missioni ed Esc agiscono alla pressione, come le finestre del gioco."
L["WN8_3_TITLE"] = "Correzioni"
L["WN8_3_TEXT"] = "Gli incantesimi si trascinano di nuovo sulla barra delle azioni 1, il nome della zona è centrato sulla barra della minimappa ovunque sia il calendario, e le schede e i comandi del famiglio del libro degli incantesimi appaiono bene."
L["WN7_1_TITLE"] = "Testo classico dei tasti"
L["WN7_1_TEXT"] = "I nomi dei tasti sui pulsanti d'azione hanno la dimensione e il contorno di Classic Era. Dimensione del testo dei tasti in Stile dei pulsanti nelle opzioni li ingrandisce o rimpicciolisce."
L["WN7_2_TITLE"] = "Posti del calendario"
L["WN7_2_TEXT"] = "Il calendario è un piccolo quadrato accanto al nome della zona; mettilo sull'anello o dietro l'icona giorno e notte in Pulsante del calendario nelle opzioni. Spunta Calendario in Minimappa di Finestre di ClassicUI Forever in modalità modifica per spostarlo o ridimensionarlo."
L["WN6_1_TITLE"] = "Pulsante del calendario"
L["WN6_1_TEXT"] = "Il calendario sta sotto l'icona giorno e notte sulla minimappa. Per nasconderlo, togli la spunta a Pulsante del calendario in Minimappa nelle opzioni."
L["WN5_1_TITLE"] = "Correzioni"
L["WN5_1_TEXT"] = "Il contrassegno dei nuovi giocatori benvenuti nella ricerca gruppi si allinea alle icone dei ruoli. Dettagli nel registro modifiche completo."
L["WN4_1_TITLE"] = "Correzioni"
L["WN4_1_TEXT"] = "Le schede prendono il mouse sulla scheda stessa, una professione lanciata dal libro degli incantesimi chiude il libro in combattimento, e l'intestazione della finestra del bottino è pulita. Dettagli nel registro modifiche completo."
L["WN3_1_TITLE"] = "Parti della barra classica"
L["WN3_1_TEXT"] = "Classic non aveva il pulsante delle professioni né la borsa dei reagenti, quindi il pulsante delle professioni esce dal micromenu (le professioni si aprono dal libro degli incantesimi) e la borsa dei reagenti è un piccolo pulsante rotondo al passaggio. Le barre 2 e 3 stanno di nuovo tra i grifoni. Entrambe sono righe in Barra classica nelle opzioni."
L["WN2_1_TITLE"] = "Modalità modifica delle finestre"
L["WN2_1_TEXT"] = "Spunta Finestre in modalità modifica per spostare e ridimensionare scheda del personaggio, libro degli incantesimi, talenti, registro delle missioni, professioni e mappa."
L["WN2_2_TITLE"] = "Profili"
L["WN2_2_TEXT"] = "Una scheda Profili nelle opzioni conserva impostazioni con nome per personaggio."
L["WN2_3_TITLE"] = "Bronzo o Scuro"
L["WN2_3_TEXT"] = "Il tema personalizzato è disponibile nel bronzo di Forever o in un antracite scuro. Vedi l'opzione Tema personalizzato."
L["WN2_4_TITLE"] = "Barra classica"
L["WN2_4_TEXT"] = "Le barre non sono più rimpicciolite per impostazione predefinita. La barra ora porta la barra della latenza, il portachiavi e la borsa dei reagenti come in classico; ognuno si può spostare in modalità modifica o nascondere in Barra classica nelle opzioni."
L["WN2_5_TITLE"] = "Pulsanti della minimappa"
L["WN2_5_TEXT"] = "I pulsanti della minimappa di altri addon possono raccogliersi dietro un pulsante sull'anello. Vedi l'opzione Raccogli i pulsanti degli addon."
L["WN2_6_TITLE"] = "Opzioni"
L["WN2_6_TEXT"] = "Sezioni Missioni e Mappa, e nuove righe per la cornice della mappa, la finestra del bottino, i tiri per il bottino, nascondere il tracciamento del gioco, il pulsante delle professioni e il testo dei tasti."
L["WN2_7_TITLE"] = "Ripristina disposizione classica"
L["WN2_7_TEXT"] = "Riporta in un colpo solo finestre, tracciamento, grifoni, parti della barra e impostazioni della disposizione."
